1	/**
2	 * Screen 05 FULL REFERENCE MATCH — Benny (`?benny05=1`, or the master `?match05=1`; qa/pilot05/full_reference_match/benny/).
3	 *
4	 * Applied to Benny HIMSELF (every screen sees the same corrected character while the switch is on), on top of the
5	 * unchanged canonical assets/models/benny.glb, rig and clips. Off (default): nothing in this file runs, every material,
6	 * geometry and shader program is the previous one.
7	 *
8	 *  1. Beanie geometry (visual only, hat-local): cuff band thinner and the whole beanie a little lower on the head, pom-pom
9	 *     lower and slightly toward his right, star re-seated — measured against the approved picture at the locked 05 frame.
10	 *  2. Swim-clip body roll damped (the clip's ±0.05 rad side wobble tipped the beanie ~13 px sideways at the pom; the
11	 *     approved Benny rides upright). Pitch bob, paddling, feet, steering lean and every gameplay transform are unchanged.
12	 *  3. Albedo maps baked from the APPROVED pixels into each part's own UV space (tools: benny/work/bake.py): the beanie's
13	 *     knit stitches / stripes / ribbed cuff, the pom-pom yarn, the cotton-candy fur colour and its shading. The maps are
14	 *     solved through the live lighting and post chain (two calibration renders: display → linear radiance = albedo·E + S),
15	 *     so the screen shows the approved colours at the locked frame and they stay glued to the 3D surfaces while he moves.
16	 *     Texels the 05 camera never sees (his front, the cuff's far side) are filled from the seen knit / fur.
17	 *  4. Finer, denser, more clumped shell fur (soft tufts instead of coarse straight spikes).
18	 */
19	import * as THREE from 'three';
20	import { flag05 } from '../../vfx/waterRibbon';
21	// ported from line B (ccr-b0757dec-dj6l1o @99ab17b, Screen 05 full-reference Benny) WITHOUT a merge (2026-11-17): on this
22	// branch it runs under `?benny05=1`, `?benny08=1` or the Screen 08 switch `?match08=1` (and `?matchall=1`); off: nothing runs
23	const on05 = (key: string): boolean => flag05(key) || flag05('benny08') || flag05('match08') || flag05('matchall');
24	import type { FurHandle, FurParams } from './fur';
25	
26	export const BENNY05: boolean = on05('benny05');
27	
28	/** shell-fur overrides (merged over the GLB's userData.fur) */
29	export const FUR05: Record<string, Partial<FurParams>> = {
30	  // (test g1, gravity 0.08: bottom 1198 → 1194 px but fringe holes 1,992 → 2,072, IoU 0.9229 → 0.9220 → rejected, kept 0.16)
31	  fur_body: { density: 96, shells: 24, length: 0.11, gravity: 0.16 },
32	  fur_armL: { density: 120, shells: 12, length: 0.05 },
33	  fur_armR: { density: 120, shells: 12, length: 0.05 },
34	  fur_pom: { density: 64, shells: 18, length: 0.12, gravity: 0.03 },
35	};
36	/** strand clumping toward tuft centres (fur.ts default 0.42) */
37	const CLUMP05: Record<string, number> = { fur_body: 0.55, fur_pom: 0.6 };
38	
39	/** beanie geometry (hat-local units; GLB build: brimBottom 0.22, cuffH 0.265, pom 0.12 above the crown apex) */
40	export const HAT05 = {
41	  /** whole beanie lowered along the body's up axis */
42	  drop: 0.028,
43	  /** whole beanie shifted toward his right (−X): the approved beanie sits ≈5 px further image-right on the body
44	   *  (r8: +0.015 back toward his left, compensating the roll's sideways swing of the cuff about the head centre) */
45	  shiftX: -0.013,
46	  /** extra backward tilt of the beanie (rad, about X; − = top toward his back) */
47	  tilt: 0,
48	  /** r8: roll of the beanie about its own forward axis (rad, + = his LEFT / image-left side up). Approved cuff bottom edge
49	   *  rises 2.65° toward the image-left relative to the game's (left 7–11 px higher, right 1–4 px lower) */
50	  roll: 0.046,
51	  /** crown dome shoulder taper (GLB build 0.18: r ∝ (1 − taper·t)); the approved dome is fuller near the top */
52	  crownTaper: 0.0,
53	  /** folded cuff band height (r8: 0.226 → 0.25, approved cuff ≈ 51 px thick vs 46–48 at the locked frame) */
54	  cuffH: 0.25,
55	  /** pom-pom core: extra offset (x = toward his LEFT, + y up) and scale (r8: pomDX −0.057 → −0.034 against the roll) */
56	  pomDX: -0.034,
57	  pomDY: -0.016,
58	  /** toward his back (−Z ≈ toward the rear chase camera): the approved pom-pom overhangs the crown's back slope */
59	  pomDZ: -0.16,
60	  pomScale: 0.97,
61	  /** star: extra offset in hat-local units after following the cuff top (r8: 0.069 → 0.062 with the thicker cuff + roll;
62	   *  r9: measured r8 star 3 px image-right and 1.7 px low of the approved → starDX +0.012 (his left), starDY 0.069) */
63	  starDY: 0.069,
64	  starDX: 0.012,
65	  /** star face scale (its own x, y) */
66	  starScale: [0.96, 0.89] as [number, number],
67	  /** cuff outer radius factor (approved cuff ≈ 297 px wide vs 291) */
68	  brimW: 1.0,
69	  /** crown dome height (GLB 0.53; r8: 0.58 → 0.556 so the thicker cuff leaves crown top and pom where they were) */
70	  crownH: 0.556,
71	};
72	
73	/** swim clip: factor on the body's side roll (z) */
74	export const ROLL05 = 0.3;
75	
76	const D = { skin: 0.7, brimBottom: 0.22, cuffH: 0.265, brimR: 0.8, crownH: 0.53 };
77	
78	function lathe(points: [number, number][], segs: number, v0: number, v1: number): THREE.LatheGeometry {
79	  const g = new THREE.LatheGeometry(points.map(([r, y]) => new THREE.Vector2(r, y)), segs);
80	  const p = g.attributes.position as THREE.BufferAttribute;
81	  const uv = g.attributes.uv as THREE.BufferAttribute;
82	  for (let i = 0; i < p.count; i++) uv.setXY(i, uv.getX(i), (p.getY(i) - v0) / (v1 - v0));
83	  return g;
84	}
85	
86	/** the GLB's beanie profiles (build.ts) with the HAT05 cuff height; u = once around (+Z front = 0, back = 0.5) */
87	function hatGeometries(cuffH: number, taper: number, crownH: number): { brim: THREE.BufferGeometry; crown: THREE.BufferGeometry; yt: number; crownTop: number } {
88	  const yb = D.brimBottom;
89	  const yt = yb + cuffH;
90	  const bk = D.brimR / 0.778;
91	  const bw = bk * HAT05.brimW;
92	  const lip = Math.sqrt(D.skin * D.skin - yb * yb) + 0.012;
93	  const brim = lathe(
94	    [
95	      [lip, yb + 0.01],
96	      [0.725 * bw, yb - 0.008],
97	      [0.758 * bw, yb + 0.02],
98	      [0.776 * bw, yb + 0.07],
99	      [0.781 * bw, yb + 0.5 * cuffH],
100	      // fuller rolled top edge (approved: the cuff's upper corners stand higher at the sides)
101	      [0.781 * bw, yt - 0.06],
102	      [0.772 * bw, yt - 0.022],
103	      [0.745 * bw, yt - 0.004],
104	      [0.69 * bk, yt],
105	    ],
106	    96,
107	    yb - 0.01,
108	    yt + 0.005,
109	  );
110	  const crownY0 = yt - 0.045;
111	  const R0 = 0.705 * bk;
112	  const prof: [number, number][] = [];
113	  for (const t of [0, 0.08, 0.16, 0.25, 0.34, 0.43, 0.52, 0.6, 0.68, 0.75, 0.81, 0.86, 0.9, 0.935, 0.96, 0.98, 0.993, 1]) {
114	    prof.push([R0 * Math.sqrt(Math.max(0, 1 - t * t)) * (1 - taper * t), crownY0 + t * crownH]);
115	  }
116	  const crown = lathe(prof, 96, crownY0, crownY0 + crownH);
117	  return { brim, crown, yt, crownTop: crownY0 + crownH };
118	}
119	
120	/** a copy of the swim clip whose body side roll is scaled by ROLL05 (the cached GLB clips stay untouched) */
121	export function dampedClips(clips: THREE.AnimationClip[]): THREE.AnimationClip[] {
122	  return clips.map((c) => {
123	    if (c.name !== 'swim') return c;
124	    const k = c.clone();
125	    for (const t of k.tracks) {
126	      if (t.name !== 'body.quaternion') continue;
127	      const q = new THREE.Quaternion(), e = new THREE.Euler();
128	      for (let i = 0; i < t.values.length; i += 4) {
129	        q.fromArray(t.values, i);
130	        e.setFromQuaternion(q, 'XYZ');
131	        e.z *= ROLL05;
132	        q.setFromEuler(e).toArray(t.values, i);
133	      }
134	    }
135	    return k;
136	  });
137	}
138	
139	// ------------------------------------------------------------------ baked maps
140	const T = (f: string) => new URL(`../../../assets/textures/benny05/${f}`, import.meta.url).href;
141	/** part → baked albedo (sRGB PNG) + colour factor (the map stores albedo / factor so it fits 0..1) + optional normal map */
142	export const MAPS05: Record<string, { map: string; scale: number; normal?: string; normalScale?: number }> = {
143	  fur_body: { map: 'body.png', scale: 1 },
144	  fur_armL: { map: 'armL.png', scale: 1 },
145	  fur_armR: { map: 'armR.png', scale: 1 },
146	  fur_pom: { map: 'pom.png', scale: 1 },
147	  hat_crown: { map: 'crown.png', scale: 1, normal: 'crown_n.png', normalScale: 0.8 },
148	  hat_brim: { map: 'brim.png', scale: 1, normal: 'brim_n.png', normalScale: 0.8 },
149	};
150	/** star: base colour (linear) solved from the approved star pixels through the 05 light + post chain (bake_report
151	 *  star_albedo_linear; the GLB's orange emissive stays and is part of the solve) → lemon yellow on screen */
152	export const STAR05 = {
153	  color: [0.319, 0.39, 0.048] as [number, number, number],
154	  /** optional baked star map (planar UVs on the star's face plane, see starUVs): face, bevel rim and highlights from the
155	   *  approved pixels; missing → the flat solved colour above */
156	  map: 'star.png',
157	};
158	
159	/** planar UVs on the star's own face plane (x, y → 0..1, square, 2 % margin): the bevel ring lands on the map's outer ring.
160	 *  The GLB star keeps its own UVs (a benny05 copy of the geometry gets these). */
161	function starUVs(src: THREE.BufferGeometry): THREE.BufferGeometry {
162	  const g = src.clone();
163	  g.computeBoundingBox();
164	  const b = g.boundingBox!;
165	  const cx = (b.min.x + b.max.x) / 2, cy = (b.min.y + b.max.y) / 2;
166	  const size = Math.max(b.max.x - b.min.x, b.max.y - b.min.y) * 1.04;
167	  const p = g.attributes.position as THREE.BufferAttribute;
168	  const uv = new Float32Array(p.count * 2);
169	  for (let i = 0; i < p.count; i++) {
170	    uv[2 * i] = (p.getX(i) - cx) / size + 0.5;
171	    uv[2 * i + 1] = (p.getY(i) - cy) / size + 0.5;
172	  }
173	  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
174	  return g;
175	}
176	
177	let loaded: Promise<Record<string, THREE.Texture | null>> | null = null;
178	/** load every baked map once (missing files → null: that part keeps its GLB look) */
179	export function loadBenny05Maps(): Promise<Record<string, THREE.Texture | null>> {
180	  if (loaded) return loaded;
181	  const files = new Set<string>();
182	  for (const m of Object.values(MAPS05)) { files.add(m.map); if (m.normal) files.add(m.normal); }
183	  files.add(STAR05.map);
184	  const tl = new THREE.TextureLoader();
185	  loaded = Promise.all(
186	    [...files].map(async (f) => {
187	      try {
188	        const t = await tl.loadAsync(T(f));
189	        t.colorSpace = f.endsWith('_n.png') ? THREE.NoColorSpace : THREE.SRGBColorSpace;
190	        t.wrapS = THREE.RepeatWrapping;
191	        // tested 16: 2,573 px changed, region numbers identical (19.35) → kept at 4
192	        t.anisotropy = 4;
193	        t.needsUpdate = true;
194	        return [f, t] as const;
195	      } catch {
196	        console.warn('[benny05] missing baked map', f);
197	        return [f, null] as const;
198	      }
199	    }),
200	  ).then((e) => Object.fromEntries(e));
201	  return loaded;
202	}
203	
204	const PART_ID: [RegExp, number][] = [
205	  [/^fur_body/, 1], [/^hat_crown/, 2], [/^hat_brim/, 3], [/^fur_pom/, 4], [/^hat_star/, 5],
206	  [/^fur_armL/, 6], [/^fur_armR/, 7], [/^fur_footL/, 8], [/^fur_footR/, 9],
207	];
208	const partId = (n: string) => PART_ID.find(([re]) => re.test(n))?.[1] ?? 10;
209	
210	export interface Benny05Handle {
211	  /** QA: render Benny's (u, v, part id, shell layer) into a float target; returns base64 Float32 RGBA of rect */
212	  uvPass(renderer: THREE.WebGLRenderer, world: THREE.Scene, camera: THREE.Camera, rect: [number, number, number, number]): string;
213	  /** QA: constant linear albedo k on every baked part (+ star), or null = back to the baked maps */
214	  calib(k: number | null): void;
215	}
216	
217	/**
218	 * Apply the corrected look to a freshly cloned Benny scene (after the fur upgrade). `maps` from loadBenny05Maps().
219	 */
220	export function applyBenny05(scene: THREE.Object3D, furs: FurHandle[], maps: Record<string, THREE.Texture | null>): Benny05Handle {
221	  const get = (n: string) => scene.getObjectByName(n);
222	  // ---- beanie geometry ----
223	  const hat = get('hat')!;
224	  hat.position.y -= HAT05.drop;
225	  hat.position.x += HAT05.shiftX;
226	  hat.rotation.x += HAT05.tilt;
227	  hat.rotation.z += HAT05.roll;
228	  const g = hatGeometries(HAT05.cuffH, HAT05.crownTaper, HAT05.crownH);
229	  const brim = get('hat_brim') as THREE.Mesh;
230	  const crown = get('hat_crown') as THREE.Mesh;
231	  brim.geometry = g.brim;
232	  crown.geometry = g.crown;
233	  const dCuff = HAT05.cuffH - D.cuffH;
234	  const star = get('hat_star') as THREE.Mesh;
235	  star.position.y += dCuff + HAT05.starDY;
236	  star.position.x += HAT05.starDX;
237	  star.scale.set(HAT05.starScale[0], HAT05.starScale[1], 1);
238	  // the roll would also turn the star 2.6° about its face: the approved star keeps its upright pose (the star's local +Z
239	  // faces back toward the camera, opposite to the hat's forward axis, hence +roll; measured: −roll gave star IoU 0.728)
240	  star.rotateZ(HAT05.roll);
241	  star.geometry = starUVs(star.geometry);
242	  const pom = get('pom')!;
243	  pom.position.y += dCuff + (HAT05.crownH - D.crownH) + HAT05.pomDY;
244	  pom.position.x += HAT05.pomDX;
245	  pom.position.z += HAT05.pomDZ;
246	  // r30 lead (user r30 "the pink character ... exactly like my approved screen", docs/briefs/2026-11-20-r30/USER_R30.md, qa/benny/r30/):
247	  // the approved 06 / storyboard Benny wears a SMALLER beanie sitting HIGHER (brim at ~53 % of his height, the dusty-pink body visible
248	  // below it) - `&b30hs=` scales the whole beanie (crown, cuff, pom, star; about the hat's own origin), `&b30hy=` raises it (hat-parent
249	  // units). Defaults 1 / 0 = unchanged.
250	  { const q = typeof location !== 'undefined' ? new URLSearchParams(location.search) : null;
251	    const hs = Number(q?.get('b30hs')) || 1, hy = Number(q?.get('b30hy')) || 0;
252	    if (hs !== 1 || hy !== 0) { hat.scale.multiplyScalar(hs); hat.position.y += hy; } }
253	  pom.scale.setScalar(HAT05.pomScale);
254	
255	  // ---- fur clumping ----
256	  for (const f of furs) {
257	    const c = CLUMP05[f.mesh.name];
258	    if (c !== undefined) f.uniforms.uClump.value = c;
259	  }
260	
261	  // ---- materials (own copies: the cached GLB materials are shared by every clone) ----
262	  const white = new THREE.DataTexture(new Uint8Array([255, 255, 255, 255]), 1, 1);
263	  white.needsUpdate = true;
264	  type St = { mesh: THREE.Mesh; mat: THREE.MeshStandardMaterial; map: THREE.Texture | null; color: THREE.Color; fur?: FurHandle; root?: THREE.Color; tip?: THREE.Color };
265	  const baked: St[] = [];
266	  scene.traverse((o) => {
267	    const m = o as THREE.Mesh;
268	    if (!m.isMesh) return;
269	    const spec = MAPS05[m.name];
270	    if (!spec) return;
271	    const fur = furs.find((f) => f.mesh === m);
272	    const mat = fur ? fur.material : (m.material as THREE.MeshStandardMaterial).clone();
273	    if (!fur) m.material = mat;
274	    const tex = maps[spec.map];
275	    if (fur) {
276	      const d = mat.defines ?? (mat.defines = {});
277	      d.BENNY05 = '';
278	    }
279	    if (tex) {
280	      if (fur) {
281	        // root → tip shading only as a relative factor on the baked colour
282	        fur.uniforms.uRoot.value.setRGB(0.86, 0.86, 0.86);
283	        fur.uniforms.uTip.value.setRGB(1, 1, 1);
284	      }
285	      mat.map = tex;
286	      mat.color.setScalar(spec.scale);
287	      if (!fur) {
288	        const n = spec.normal ? maps[spec.normal] : null;
289	        mat.normalMap = n;
290	        if (n) mat.normalScale.setScalar(spec.normalScale ?? 1);
291	      }
292	    } else if (fur) {
293	      // no bake yet: keep the GLB root / tip colours through the multiply path
294	      mat.map = white;
295	    } else if (m.name === 'hat_crown' && mat.map) {
296	      mat.map = mat.map.clone();
297	      mat.map.repeat.x = 4; // GLB crown texture was authored for a 4× u repeat
298	      mat.map.needsUpdate = true;
299	      if (mat.normalMap) { mat.normalMap = mat.normalMap.clone(); mat.normalMap.repeat.x = 4; mat.normalMap.needsUpdate = true; }
300	    }
301	    mat.needsUpdate = true;
302	    baked.push({ mesh: m, mat, map: mat.map, color: mat.color.clone(), fur, root: fur?.uniforms.uRoot.value.clone(), tip: fur?.uniforms.uTip.value.clone() });
303	  });
304	  const starMat = (star.material as THREE.MeshStandardMaterial).clone();
305	  const starTex = maps[STAR05.map] ?? null;
306	  if (starTex) {
307	    starTex.wrapS = starTex.wrapT = THREE.ClampToEdgeWrapping;
308	    starMat.map = starTex;
309	    starMat.color.setScalar(1);
310	  } else starMat.color.setRGB(...STAR05.color);
311	  starMat.needsUpdate = true;
312	  star.material = starMat;
313	  const starCol = starMat.color.clone();
314	
315	  // ---- QA hooks ----
316	  const uvPass: Benny05Handle['uvPass'] = (renderer, world, camera, rect) => {
317	    const size = renderer.getDrawingBufferSize(new THREE.Vector2());
318	    const rt = new THREE.WebGLRenderTarget(size.x, size.y, { type: THREE.FloatType, depthBuffer: true });
319	    const root = scene.parent!;
320	    const vis: [THREE.Object3D, boolean][] = [];
321	    for (const c of world.children) { vis.push([c, c.visible]); if (c !== root) c.visible = false; }
322	    const bg = world.background;
323	    world.background = null;
324	    const saved: [THREE.Mesh, THREE.Material | THREE.Material[]][] = [];
325	    const tmp: THREE.Material[] = [];
326	    scene.traverse((o) => {
327	      const m = o as THREE.Mesh;
328	      if (!m.isMesh) return;
329	      const id = partId(m.name);
330	      const fur = furs.find((f) => f.mesh === m);
331	      if (fur) {
332	        const d = fur.material.defines ?? (fur.material.defines = {});
333	        if (d.BENNY05 === undefined) { d.BENNY05 = ''; d.B05_TMP = ''; }
334	        d.BENNY_UV = '';
335	        fur.uniforms.uMaskCol.value.setRGB(id, 0, 0);
336	        fur.material.needsUpdate = true;
337	        return;
338	      }
339	      saved.push([m, m.material]);
340	      const side = (m.material as THREE.Material).side;
341	      const sm = new THREE.ShaderMaterial({
342	        uniforms: { uId: { value: id } },
343	        vertexShader: 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
344	        fragmentShader: 'uniform float uId; varying vec2 vUv; void main(){ gl_FragColor = vec4(vUv, uId, 0.0); }',
345	        side,
346	      });
347	      tmp.push(sm);
348	      m.material = sm;
349	    });
350	    const prevTarget = renderer.getRenderTarget();
351	    const prevClear = renderer.getClearColor(new THREE.Color());
352	    const prevAlpha = renderer.getClearAlpha();
353	    renderer.setRenderTarget(rt);
354	    renderer.setClearColor(0x000000, 0);
355	    renderer.clear();
356	    renderer.render(world, camera);
357	    const [x, y, w, h] = rect;
358	    const buf = new Float32Array(w * h * 4);
359	    renderer.readRenderTargetPixels(rt, x, size.y - y - h, w, h, buf);
360	    renderer.setRenderTarget(prevTarget);
361	    renderer.setClearColor(prevClear, prevAlpha);
362	    for (const [m, mat] of saved) m.material = mat;
363	    for (const t of tmp) t.dispose();
364	    for (const f of furs) {
365	      const d = f.material.defines;
366	      if (d?.BENNY_UV !== undefined) { delete d.BENNY_UV; f.material.needsUpdate = true; }
367	      if (d?.B05_TMP !== undefined) { delete d.B05_TMP; delete d.BENNY05; }
368	    }
369	    for (const [c, v] of vis) c.visible = v;
370	    world.background = bg;
371	    rt.dispose();
372	    const bytes = new Uint8Array(buf.buffer);
373	    let s = '';
374	    for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
375	    return btoa(s);
376	  };
377	  const calib: Benny05Handle['calib'] = (k) => {
378	    for (const b of baked) {
379	      b.mat.map = k === null ? b.map : white;
380	      if (k === null) b.mat.color.copy(b.color); else b.mat.color.setScalar(k);
381	      if (b.fur) {
382	        // calibration always sees the baked-mode relative root → tip factor
383	        if (k === null) { b.fur.uniforms.uRoot.value.copy(b.root!); b.fur.uniforms.uTip.value.copy(b.tip!); }
384	        else { b.fur.uniforms.uRoot.value.setRGB(0.86, 0.86, 0.86); b.fur.uniforms.uTip.value.setRGB(1, 1, 1); }
385	      }
386	      b.mat.needsUpdate = true;
387	    }
388	    if (k === null) starMat.color.copy(starCol); else starMat.color.setScalar(k);
389	    if (starTex) { starMat.map = k === null ? starTex : white; starMat.needsUpdate = true; }
390	  };
391	  return { uvPass, calib };
392	}
393

diff --git a/src/characters/benny/benny05.ts b/src/characters/benny/benny05.ts
index 142e6c3c..94c18d88 100644
