380	    crownProfile.push([R0 * Math.sqrt(Math.max(0, 1 - t * t)) * (1 - 0.18 * t), crownY0 + t * D.crownH]);
381	  }
382	  const crown = named(
383	    new THREE.Mesh(lathe(crownProfile, 72, crownY0, crownY0 + D.crownH, CROWN_REPEAT), crownMat),
384	    'hat_crown',
385	  );
386	  hat.add(crown);
387	  // puffy gold star badge sewn on the lower white stripe just above the cuff, rear-RIGHT (−X): image-right of
388	  // centre in the rear gameplay views (ref 05: centre at ≈ +0.68 of the cuff half-width, ≈ 0.11 × the cuff width
389	  // above the cuff's top edge, ≈ 0.27 × the cuff width across, its lower points overlapping the cuff). Its face
390	  // is turned toward the back (normal 160° from the front) and leans back against the sloping crown (tilted 25°
391	  // up), so the rear ride cameras (10–25° above Benny) see it face-on, never edge-on.
392	  const starGeo = new THREE.ExtrudeGeometry(starShape(0.165, 0.083), {
393	    depth: 0.02,
394	    bevelEnabled: true,
395	    bevelThickness: 0.045,
396	    bevelSize: 0.032,
397	    bevelSegments: 4,
398	  });
399	  starGeo.center();
400	  const star = named(
401	    new THREE.Mesh(starGeo, std({ color: C.gold, metalness: 0.12, roughness: 0.3, emissive: '#ffb800', emissiveIntensity: 0.22 })),
402	    'hat_star',
403	  );
404	  const sa = THREE.MathUtils.degToRad(D.starAng);
405	  // wave 4: centred on the cuff's top edge (ref 05: ≈ 40 % of the star on the cuff, the rest on the white band);
406	  // leans back only 12° because the runtime's ride lean (≈ 13°) tips it the rest of the way toward the chase camera
407	  const starPos = new THREE.Vector3(-Math.sin(sa) * D.starR, yt + D.starY, Math.cos(sa) * D.starR);
408	  const na = THREE.MathUtils.degToRad(160), tilt = THREE.MathUtils.degToRad(12);
409	  const starN = new THREE.Vector3(-Math.sin(na) * Math.cos(tilt), Math.sin(tilt), Math.cos(na) * Math.cos(tilt));
410	  star.position.copy(starPos);
411	  star.lookAt(starPos.clone().add(starN));
412	  star.rotateZ(-0.14);
413	  hat.add(star);
414	  // big fluffy-round pom-pom sitting ON the crown apex (≈ 0.5 × the cuff width wide and ≈ 0.46 × tall above the
415	  // crown in ref 05; wave 3 raised it out of the crown and moved it back over the apex against the forward tilt)
416	  // wave 4: core centre 0.12 above the dome apex → the lower third of the pom nests in the dome (ref 05: the top purple
417	  // band shows around its base), slightly to the back so the ride lean keeps it centred over the dome
418	  const pom = joint('pom', 0, crownY0 + D.crownH + 0.12, -0.05);
419	  hat.add(pom);
420	  const pomMesh = named(new THREE.Mesh(new THREE.SphereGeometry(D.pomR, 32, 24), std({ color: C.pomRoot, roughness: 0.95 })), 'fur_pom');
421	  // short, dense strands with little droop → a round plush ball rather than a spiky urchin
422	  pomMesh.userData = furData({ length: 0.12, density: 88, shells: 16, root: C.pomRoot, tip: C.pomTip, gravity: 0.05 });
423	  pom.add(pomMesh);
424	
425	  const animations = buildClips();
426	  return { scene: root, animations };
427	}
