1	/**
2	 * Runtime Benny: loads the canonical assets/models/benny.glb, upgrades fur_* meshes to shell fur,
3	 * and drives expressions + procedural secondary motion on top of the GLB clips.
4	 */
5	import * as THREE from 'three';
6	import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
7	import type { BennyRuntime } from '../types';
8	import { makeFur, type FurHandle, type FurParams } from './fur';
9	import { BENNY05, FUR05, applyBenny05, dampedClips, loadBenny05Maps } from './benny05';
10	
11	const BENNY_URL = new URL('../../../assets/models/benny.glb', import.meta.url).href;
12	
13	let cached: Promise<THREE.Group> | null = null;
14	
15	function loadScene(): Promise<THREE.Group> {
16	  if (!cached) cached = new GLTFLoader().loadAsync(BENNY_URL).then((g) => {
17	    const s = g.scene as THREE.Group;
18	    s.userData.animations = g.animations;
19	    return s;
20	  });
21	  return cached;
22	}
23	
24	/** fur tier: explicit option, else `?quality=low|high`, else low on Android/iOS (same rule as the water) */
25	function defaultFurQuality(): 'high' | 'low' {
26	  if (typeof location === 'undefined') return 'high';
27	  const qp = new URLSearchParams(location.search).get('quality');
28	  const mobile = typeof navigator !== 'undefined' && /Android|iPhone|iPad/i.test(navigator.userAgent);
29	  return qp === 'low' || (qp !== 'high' && mobile) ? 'low' : 'high';
30	}
31	
32	export async function loadBenny(opts: { furQuality?: 'high' | 'low' } = {}): Promise<BennyRuntime> {
33	  const src = await loadScene();
34	  const clips: THREE.AnimationClip[] = src.userData.animations ?? [];
35	  // `?benny05=1` / `?match05=1` only: the maps baked from the approved Screen 05 (benny05.ts)
36	  const maps05 = BENNY05 ? await loadBenny05Maps() : undefined;
37	  return createBennyRuntime(src.clone(true), clips, { furQuality: opts.furQuality ?? defaultFurQuality(), maps05 });
38	}
39	
40	/**
41	 * Ride height. The game places the root at water surface + radius·0.55 (≈ 0.44), which buried the lower
42	 * third of the plush ball in the opaque stream. While riding (swim ≥ 0.5, not tumbling) the model is
43	 * lifted inside the root so he sits ON the water like refs 04–10: only the bottom of the fur and the
44	 * kicking feet are under the surface. Cinematics (01 peek, 02 tumble, 11 hide) keep the root as placed.
45	 * Wave 4: 0.30 → 0.22 together with the ride lean, which shows more of his back: keeps the pom-pom top at the
46	 * ref-05 height (≈ 765 px, under the first coin) and the cuff bottom where the ref has it.
47	 * Wave 5: 0.22 → 0.12. Measured in the live 05 capture with the re-exported GLB (flat-ID mask): 0.22 put the pom top at
48	 * 748 and the bottom at 1178; 0.12 gives bbox x 231–612 / y 766–1188, cuff bottom 1029, hat incl. pom 62 % / body 38 %
49	 * (ref 05: x 230–612 / y 767–≈1185, cuff bottom ≈ 1028).
50	 */
51	export const BENNY_RIDE_LIFT = 0.12;
52	/** QA A/B hook: `?bennyLift=<units>` overrides the ride lift (e.g. 0 = the game's raw placement) */
53	function rideLift(): number {
54	  if (typeof location === 'undefined') return BENNY_RIDE_LIFT;
55	  const v = parseFloat(new URLSearchParams(location.search).get('bennyLift') ?? '');
56	  return Number.isFinite(v) ? THREE.MathUtils.clamp(v, 0, 0.6) : BENNY_RIDE_LIFT;
57	}
58	
59	/**
60	 * Ride lean (rad, about his X axis, + = top forward). While riding he leans into the current like a swimmer, so the
61	 * rear chase cameras (04–10: ≈ 25° above him) see the beanie and the plush back the way the references paint
62	 * them (≈ 10–12° above: knit stripes and cuff read as level bands, the dome as a tall cap, not a flat disc).
63	 * Eased in with the ride lift; cinematics (01 peek, 02 tumble, 11 hide) keep him upright. The game can scale it
64	 * per shot with `benny.root.userData.ridePitch` (0…1, default 1), e.g. 0 in the 03 twirl where he faces the camera.
65	 */
66	export const BENNY_RIDE_PITCH = 0.22;
67	function ridePitch(): number {
68	  if (typeof location === 'undefined') return BENNY_RIDE_PITCH;
69	  const v = parseFloat(new URLSearchParams(location.search).get('bennyPitch') ?? '');
70	  return Number.isFinite(v) ? THREE.MathUtils.clamp(THREE.MathUtils.degToRad(v), -0.5, 0.5) : BENNY_RIDE_PITCH;
71	}
