73	/** Build the runtime around an already-loaded (or freshly built) Benny scene graph. */
74	export function createBennyRuntime(
75	  scene: THREE.Object3D,
76	  clips: THREE.AnimationClip[],
77	  opts: { furQuality?: 'high' | 'low'; maps05?: Record<string, THREE.Texture | null> } = {},
78	): BennyRuntime {
79	  const root = new THREE.Group();
80	  root.name = 'Benny';
81	  root.add(scene);
82	
83	  // ---- fur upgrade ----
84	  const furs: FurHandle[] = [];
85	  const toReplace: THREE.Mesh[] = [];
86	  scene.traverse((o) => {
87	    const m = o as THREE.Mesh;
88	    if (m.isMesh && m.name.startsWith('fur_') && m.userData?.fur) toReplace.push(m);
89	  });
90	  for (const m of toReplace) {
91	    const p = { ...(m.userData.fur as FurParams) };
92	    if (BENNY05 && FUR05[m.name]) Object.assign(p, FUR05[m.name]);
93	    if (opts.furQuality === 'low') p.shells = Math.max(6, Math.round(p.shells * 0.6));
94	    const h = makeFur(m, p);
95	    m.parent!.add(h.mesh);
96	    m.parent!.remove(m);
97	    furs.push(h);
98	  }
99	  // `?benny05=1` / `?match05=1`: the Screen-05 reference-matched look, on Benny himself (benny05.ts). Off: nothing runs.
100	  const b05 = BENNY05 ? applyBenny05(scene, furs, opts.maps05 ?? {}) : null;
101	  if (BENNY05) clips = dampedClips(clips);
102	
103	  // QA colour A/B: `?bennyTint=hat_brim:7868a0,hat_crown:e4d4e4` sets the base-colour factor of meshes whose name
104	  // starts with the given prefix (the GLB's own factors are the default; materials are shared by every clone)
105	  if (typeof location !== 'undefined') {
106	    const tint = new URLSearchParams(location.search).get('bennyTint');
107	    for (const kv of tint ? tint.split(',') : []) {
108	      const [prefix, hex] = kv.split(':');
109	      if (!prefix || !/^[0-9a-f]{6}$/i.test(hex ?? '')) continue;
110	      scene.traverse((o) => {
111	        const m = o as THREE.Mesh;
112	        if (m.isMesh && m.name.startsWith(prefix)) (m.material as THREE.MeshStandardMaterial).color?.set(`#${hex}`);
113	      });
114	    }
115	  }
116	
117	  const get = (n: string) => scene.getObjectByName(n)!;
118	  const body = get('body');
119	  const pom = get('pom');
120	  const eyeL = get('eyeL');
121	  const eyeR = get('eyeR');
122	  const eyesGroup = get('eyes');
123	  const pomRest = pom.quaternion.clone();
124	
125	  // ---- animation mixer: idle ↔ swim blend, tumble / peek on demand ----
126	  const mixer = new THREE.AnimationMixer(scene);
127	  const act = (name: string) => {
128	    const c = clips.find((k) => k.name === name);
129	    return c ? mixer.clipAction(c) : null;
130	  };
131	  const aIdle = act('idle'), aSwim = act('swim'), aTumble = act('tumble'), aPeek = act('peek');
132	  for (const a of [aIdle, aSwim, aTumble, aPeek]) a?.play();
133	  const setW = (a: THREE.AnimationAction | null, w: number) => a && a.setEffectiveWeight(w);
134	
135	  let expression: 'happy' | 'dizzy' | 'peek' = 'happy';
136	  const setExpression = (e: 'happy' | 'dizzy' | 'peek') => {
137	    expression = e;
138	    for (const s of ['L', 'R']) {
139	      const h = scene.getObjectByName(`eye${s}_happy`);
140	      const d = scene.getObjectByName(`eye${s}_dizzy`);
141	      if (h) h.visible = e !== 'dizzy';
142	      if (d) d.visible = e === 'dizzy';
143	    }
144	    for (const k of ['happy', 'dizzy', 'peek']) {
145	      const m = scene.getObjectByName(`mouth_${k}`);
146	      if (m) m.visible = k === e;
147	    }
148	    eyesGroup.scale.setScalar(e === 'peek' ? 1.06 : 1);
149	  };
150	  setExpression('happy');
151	
152	  // ---- secondary motion state ----
153	  let pomAngX = 0, pomVelX = 0, pomAngZ = 0, pomVelZ = 0;
154	  let lastY = 0, lastVy = 0;
155	  let blinkT = 1.7;
156	  let lean = 0;
157	  let lift = 0;
158	  const liftMax = rideLift();
159	  let pitch = 0;
160	  const pitchMax = ridePitch();
161	  const tmp = new THREE.Vector3();
162	  const qLean = new THREE.Quaternion();
163	  const qPom = new THREE.Quaternion();
164	  const eAxis = new THREE.Euler();
165	
166	  const update: BennyRuntime['update'] = (dt, st) => {
167	    dt = Math.min(dt, 1 / 20);
168	    // clip weights
169	    const tumble = !!st.tumble;
170	    const swim = tumble ? 0 : THREE.MathUtils.clamp(st.swim, 0, 1);
171	    const peek = expression === 'peek' && !tumble ? 1 : 0;
172	    setW(aTumble, tumble ? 1 : 0);
173	    setW(aPeek, peek);
174	    setW(aSwim, peek ? 0 : swim);
175	    setW(aIdle, tumble || peek ? 0 : 1 - swim);
176	    if (aSwim) aSwim.timeScale = 0.8 + Math.min(1.2, st.speed / 14);
177	    mixer.update(dt);
178	
179	    // ride height (see BENNY_RIDE_LIFT): eased so mode switches never pop
180	    const liftTarget = tumble || peek ? 0 : liftMax * THREE.MathUtils.smoothstep(swim, 0.5, 0.9);
181	    lift += (liftTarget - lift) * (1 - Math.exp(-dt * 7));
182	    scene.position.y = lift;
183	    // ride lean into the current (see BENNY_RIDE_PITCH), on the same ease as the lift
184	    const pitchScale = typeof root.userData.ridePitch === 'number' ? THREE.MathUtils.clamp(root.userData.ridePitch, 0, 1) : 1;
185	    const pitchTarget = tumble || peek ? 0 : pitchMax * pitchScale * THREE.MathUtils.smoothstep(swim, 0.5, 0.9);
186	    pitch += (pitchTarget - pitch) * (1 - Math.exp(-dt * 7));
187	
188	    // steering lean (roll) + slight yaw into the turn
189	    lean += (THREE.MathUtils.clamp(st.steer, -1, 1) * 0.28 - lean) * Math.min(1, dt * 6);
190	    qLean.setFromEuler(eAxis.set(pitch, -lean * 0.6, -lean));
191	    body.quaternion.multiply(qLean);
192	
193	    // pom-pom spring: driven by vertical acceleration, steering and speed jitter
194	    root.getWorldPosition(tmp);
195	    const vy = (tmp.y - lastY) / Math.max(dt, 1e-3);
196	    const ay = THREE.MathUtils.clamp((vy - lastVy) / Math.max(dt, 1e-3), -80, 80);
197	    lastY = tmp.y; lastVy = vy;
198	    const k = 120, c = 9;
199	    const targetX = -ay * 0.004 + Math.sin(st.time * 11) * 0.03 * Math.min(1, st.speed / 12);
200	    const targetZ = lean * 0.9;
201	    pomVelX += (k * (targetX - pomAngX) - c * pomVelX) * dt;
202	    pomAngX += pomVelX * dt;
203	    pomVelZ += (k * (targetZ - pomAngZ) - c * pomVelZ) * dt;
204	    pomAngZ += pomVelZ * dt;
205	    qPom.setFromEuler(eAxis.set(THREE.MathUtils.clamp(pomAngX, -0.6, 0.6), 0, THREE.MathUtils.clamp(pomAngZ, -0.6, 0.6)));
206	    pom.quaternion.copy(pomRest).multiply(qPom);
207	
208	    // blink (cartoon squash of the eyes); no blinking while dizzy
209	    blinkT -= dt;
210	    let blink = 1;
211	    if (expression !== 'dizzy') {
212	      if (blinkT < 0.14) blink = Math.abs(blinkT - 0.07) / 0.07;
213	      if (blinkT <= 0) blinkT = 2.2 + Math.random() * 2.6;
214	    }
215	    eyeL.scale.y = eyeR.scale.y = Math.max(0.08, blink);
216	
217	    for (const f of furs) {
218	      f.uniforms.uTime.value = st.time;
219	      f.uniforms.uWind.value.set(0, 0, -Math.min(0.6, st.speed / 25));
220	    }
221	  };
222	
223	  // ---- QA segmentation mask (`?bennyMask`, or window.__bennyQA.mask(true) in ?qa pages) ----
224	  if (typeof location !== 'undefined') {
225	    const qs = new URLSearchParams(location.search);
226	    const qa = { mask: (on: boolean) => setMask(scene, furs, on), info: () => qaInfo(root, body), b05 };
227	    if (qs.has('qa') || qs.has('bennyMask')) (window as unknown as { __bennyQA?: typeof qa }).__bennyQA = qa;
228	    if (qs.has('bennyMask')) qa.mask(true);
229	  }
230	
231	  return { root, setExpression, update, radius: 0.8 };
232	}
233	
234	/**
235	 * Flat ID colours for pixel measurement in real game captures (no lighting, fog or textures):
236	 * body fur / arms / feet / face = red, beanie crown = cyan, ribbed cuff = blue, pom-pom = green, star = black.
237	 * Classify the frame with  R>150,G<60,B<60 (body) · G>150,R<60,B<60 (pom) · B>150,R<60,G<60 (cuff) ·
238	 * R<60,G>150,B>150,|G−B|<40 (crown) · all<40 inside the hat (star).
239	 */
240	const MASK_COLS: [RegExp, string][] = [
241	  [/^fur_pom/, '#00ff00'],
242	  [/^hat_crown/, '#00ffff'],
243	  [/^hat_brim/, '#0000ff'],
244	  [/^hat_star/, '#000000'],
245	];
246	function maskColour(name: string): string {
247	  for (const [re, c] of MASK_COLS) if (re.test(name)) return c;
248	  return '#ff0000';
249	}
250	function setMask(scene: THREE.Object3D, furs: FurHandle[], on: boolean): void {
251	  for (const f of furs) {
252	    f.uniforms.uMaskCol.value.set(maskColour(f.mesh.name));
253	    const d = f.material.defines ?? (f.material.defines = {});
254	    if (on) d.BENNY_MASK = ''; else delete d.BENNY_MASK;
255	    f.material.needsUpdate = true;
256	  }
257	  scene.traverse((o) => {
258	    const m = o as THREE.Mesh;
259	    if (!m.isMesh || (m as unknown as THREE.InstancedMesh).isInstancedMesh) return;
260	    const ud = m.userData as { qaOrig?: THREE.Material | THREE.Material[]; qaVis?: boolean };
261	    if (on && !ud.qaOrig) {
262	      ud.qaOrig = m.material;
263	      ud.qaVis = m.visible;
264	      // face decals sit on the red body: hide them so their alpha edges do not leak texture colours
265	      if (/^(blush|mouth_)/.test(m.name)) m.visible = false;
266	      m.material = new THREE.MeshBasicMaterial({ color: maskColour(m.name), fog: false });
267	    } else if (!on && ud.qaOrig) {
268	      (m.material as THREE.Material).dispose();
269	      m.material = ud.qaOrig;
270	      m.visible = ud.qaVis ?? true;
271	      delete ud.qaOrig;
272	    }
273	  });
274	}
275	function qaInfo(root: THREE.Object3D, body: THREE.Object3D) {
276	  const p = body.getWorldPosition(new THREE.Vector3());
277	  const up = new THREE.Vector3(0, 1, 0).applyQuaternion(root.getWorldQuaternion(new THREE.Quaternion()));
278	  const fwd = new THREE.Vector3(0, 0, 1).applyQuaternion(root.getWorldQuaternion(new THREE.Quaternion()));
279	  const r3 = (v: THREE.Vector3) => v.toArray().map((x) => +x.toFixed(3));
280	  return { body: r3(p), up: r3(up), fwd: r3(fwd), scale: +root.scale.x.toFixed(3) };
281	}
